
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_tlda_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_tlda", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.202602842514789e+00, -3.162609017375748e+00, -3.105997047217179e+00, -3.026450221522967e+00, -2.915878626787301e+00, -2.764587340295658e+00, -2.562234457168582e+00, -2.300130657385906e+00, -1.975259208422589e+00, -1.595894240685926e+00, -1.189699421128127e+00, -8.179168131081778e-01, -5.650730793879754e-01, -4.581901775261161e-01, -3.608667644391442e-01, -2.520542921810768e-01, -1.529166271975171e-01, -7.735033688188730e-02, -3.021268095282408e-02, -8.052351494932818e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


